import * as THREE from 'three/webgpu';
import { texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-2-label';

  const position = config.scenePosition?.position ?? [3.2, 1, 0.06];
  const rotation = config.scenePosition?.rotation ?? [0, 0, 0];
  const scale = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const width = 1.6;
  const height = width * (320 / 512);
  const geometry = new THREE.PlaneGeometry(width, height);

  const imageTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  const atlasWidth = 512;
  const atlasHeight = 320;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const uMin = rect.x / atlasWidth;
  const uMax = (rect.x + rect.w) / atlasWidth;
  const vMin = 1 - (rect.y + rect.h) / atlasHeight;
  const vMax = 1 - rect.y / atlasHeight;

  const uvNode = uv();

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(imageTexture, uvNode.mul(
    new THREE.Vector2(uMax - uMin, vMax - vMin)
  ).add(new THREE.Vector2(uMin, vMin)));
  material.transparent = true;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'card-image';
  group.add(plane);

  const textContent = config.textContent ?? [
    { text: 'Collection 3', role: 'headline', size: 39, weight: 400 },
  ];

  const textMeshes = [];

  textContent.forEach((item, index) => {
    const textMesh = ctx.fontAtlas.createText({
      text: item.text,
      font: 'display',
      weight: item.weight ?? 400,
      size: 0.34,
      color: colors.paper,
      align: 'left',
      anchor: 'center',
    });
    textMesh.name = `card-label-text-${index}`;
    textMesh.position.set(0, -height / 2 + 0.2, 0.01);
    group.add(textMesh);
    textMeshes.push(textMesh);
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imageTexture && imageTexture.dispose) imageTexture.dispose();
    textMeshes.forEach((textMesh) => {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach((m) => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    });
  };

  return group;
}
